return ['domain'=>'askparla-ai-shopping-assistant','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fr_FR','project-id-version'=>'AskParla AI Shopping Assistant for WooCommerce','pot-creation-date'=>'2026-10-09T21:02:15+00:00','po-revision-date'=>'2026-10-09 21:00+0000','messages'=>['Parla account'=>'Compte Parla','paused'=>'en pause','The chat server is up, but your Parla account is paused, so shoppers see a connection error. Choose a plan in your Parla account, or write to us, and it answers again within the minute.'=>'Le serveur du chat fonctionne, mais votre compte Parla est en pause : vos clients voient une erreur de connexion. Choisissez une formule dans votre compte Parla, ou écrivez-nous, et le chat répond de nouveau dans la minute.','AskParla AI Shopping Assistant for WooCommerce'=>'AskParla AI Shopping Assistant for WooCommerce','https://askparla.com'=>'https://askparla.com','AI shopping and order-support chat for your store: product search, order tracking, address changes and returns.'=>'Un chat d’achat et de service client par IA pour votre boutique : recherche de produits, suivi de commande, changement d’adresse et retours.','AskParla'=>'AskParla','the server answered %d'=>'le serveur a répondu %d','Show'=>'Afficher','Copied'=>'Copié','Copy'=>'Copier','%1$s different things, asked %2$s times'=>'%1$s demandes différentes, posées %2$s fois','%s thing asked'=>'%s demande' . "\0" . '%s demandes différentes','Show fewer'=>'Afficher moins','Show %s more'=>'Afficher %s de plus','Showing the busiest %s. The rest are in your Parla dashboard.'=>'Les %s plus fréquentes sont affichées. Les autres sont dans votre espace Parla.','Sales it helped with'=>'Ventes auxquelles il a contribué','Last 30 days'=>'30 derniers jours','No orders yet from shoppers who talked to the assistant. An order counts when it is placed within 7 days of a chat or a call.'=>'Aucune commande pour l’instant de clients ayant parlé à l’assistant. Une commande compte si elle est passée d